const itemsCards = $('Obtener Metricas').all();
const itemsVentas = $('Obtener Ventas').all();
const itemsTop = $('Obtener Top Libros').all();
const itemsErrores = $('Obtener Errores Pago').all();

function firstJson(items) {
  const item = Array.isArray(items) ? items[0] : null;
  return (item && item.json) ? item.json : {};
}

const metricasCards = firstJson(itemsCards);
const metricasVentas = firstJson(itemsVentas);
const metricasTop = firstJson(itemsTop);
const metricasErrores = firstJson(itemsErrores);

function parseMetricasPagos(text) {
  const resultado = { exitos: 0, fallos: 0, razonUltimoError: null };
  const lines = String(text || '').split('\n');
  for (const line of lines) {
    const m = line.match(/^rayuela_payment_failure_total(?:\{.*\})?\s+([\d.]+)/);
    if (m) {
      resultado.fallos = Number(m[1]);
      const rm = line.match(/reason="([^"]*)"/);
      resultado.razonUltimoError = rm ? rm[1] : null;
    }
    const m2 = line.match(/^rayuela_payment_success_total(?:\{.*\})?\s+([\d.]+)/);
    if (m2) {
      resultado.exitos = Number(m2[1]);
    }
  }
  return resultado;
}

const rawErrores = (metricasErrores && typeof metricasErrores === 'object' && metricasErrores.data !== undefined) ? metricasErrores.data : metricasErrores;
const metricasPagos = parseMetricasPagos(rawErrores);
const metricas = {
  ingresos: metricasCards.ingresos || null,
  reservasActivas: metricasCards.reservasActivas !== undefined ? metricasCards.reservasActivas : 0,
  bajoStockCritico: metricasCards.bajoStockCritico !== undefined ? metricasCards.bajoStockCritico : 0,
  ventasMensuales: Array.isArray(metricasVentas) ? metricasVentas : [],
  topLibros: Array.isArray(metricasTop) ? metricasTop : [],
  metricasPagos: metricasPagos,
};

// Fecha de hoy en la zona horaria del negocio (Jujuy), formato AAAA-MM-DD. Si el entorno no soporta zonas
// horarias, se usa la fecha UTC.
let fecha;
try {
  fecha = new Date().toLocaleDateString('sv-SE', { timeZone: 'America/Argentina/Jujuy' });
} catch (e) {
  fecha = new Date().toISOString().slice(0, 10);
}
const [anio, mes, dia] = fecha.split('-');
const fechaLegible = dia + '/' + mes + '/' + anio;

const prompt = [
  'Sos el analista ejecutivo de la libreria online Rayuela.',
  'Fecha de emision del informe: ' + fechaLegible + '. Usa exactamente esta fecha; no inventes ni cambies la fecha.',
  'Genera un informe ejecutivo formal en Markdown a partir de las siguientes metricas semanales:',
  JSON.stringify(metricas),
  'El informe debe contener: resumen ejecutivo, metricas de negocio (ventas e ingresos), metricas operativas (reservas activas y stock critico), metricas de pagos y conclusiones.',
].join('\n');

const ncUser = (typeof process !== 'undefined' && process.env && process.env.NC_ADMIN_USER) || 'admin';

return [{
  json: {
    prompt: prompt,
    metrics: metricas,
    informeFile: 'informe-' + fecha + '.md',
    ncUser: ncUser,
  },
}];

const data = $json || {};
const candidate = (data.candidates && data.candidates[0]) ? data.candidates[0] : null;
const parts = candidate && candidate.content ? candidate.content.parts : [];
const text = (parts && parts[0] && parts[0].text) ? parts[0].text : '';
const prev = $('Consolidar Metricas').all();
const prevItem = Array.isArray(prev) ? prev[0] : null;
const prevJson = (prevItem && prevItem.json) ? prevItem.json : {};
return [{
  json: {
    informe: text,
    ncUser: prevJson.ncUser,
    informeFile: prevJson.informeFile,
  },
}];

const entries = Array.isArray(items) ? items : [items];
for (const item of entries) {
  const data = item.json || {};
  const err = data.error || data;
  const nodeName = (data.node && data.node.name) || data.nodeName || data.node || 'desconocido';
  console.error(JSON.stringify({
    ts: new Date().toISOString(),
    source: 'n8n-fl3-error-node',
    workflow: $workflow.name,
    executionId: $execution.id,
    node: typeof nodeName === 'string' ? nodeName : JSON.stringify(nodeName),
    message: err.message || String(err),
    description: err.description || null,
    stack: err.stack || null,
  }, null, 2));
}
return [];
